package com.projecteden.village.controller;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.user.domain.User;import com.projecteden.village.dto.*;import com.projecteden.village.service.VillageService;@RestController@RequestMapping("/api/village")public class VillageController{private final VillageService service;public VillageController(VillageService service){this.service=service;}@GetMapping("/me")public VillageResponse village(@AuthenticationPrincipal User user){return service.getVillageByUserId(user.getId());}@GetMapping("/history")public List<VillageHistoryResponse> history(@AuthenticationPrincipal User user){return service.getHistoryByUserId(user.getId());}@GetMapping("/changes")public List<VillageChangeResponse> changes(@AuthenticationPrincipal User user){return service.getChangesByUserId(user.getId());}}
